import{_ as o}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/OFF.BrU7kQE-.js";import{_ as i}from"./chunks/DIS.DdpTdGGD.js";import{_ as e}from"./chunks/EN.P9aPnFBv.js";import{_ as s,a as n,b as l}from"./chunks/M-S-LCS11a.DEHuJb6u.js";import{_ as r,o as p,c as d,a3 as m}from"./chunks/framework.g9mfNVRQ.js";const I=JSON.parse('{"title":"Impostazioni meno usate","description":"","frontmatter":{"source_hash":"702fd175c0","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/use/lesscommon.md","filePath":"it/use/lesscommon.md"}'),c={name:"it/use/lesscommon.md"};function u(v,t,g,b,z,h){return p(),d("div",null,[...t[0]||(t[0]=[m('<div class="admonition xdrip"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"></p><p> Impostazioni<br>   Impostazioni Meno Usate</p></div><p>Altre impostazioni di xDrip sono disponibili in Impostazioni Meno Usate.<br> Se non trovi l&#39;impostazione che cerchi, ricorda che puoi usare la lente di ricerca dal menu principale delle <a href="./settings.html">impostazioni</a>.</p><h3 id="extra-status-line" tabindex="-1">Riga di stato extra <a class="header-anchor" href="#extra-status-line" aria-label="Permalink to &quot;Riga di stato extra {#extra-status-line}&quot;">​</a></h3><p>In alto a sinistra del grafico principale vedi la riga di stato standard.<br> Questo menu ti permette di aggiungere informazioni extra in quest&#39;area.</p><div class="admonition xdripitem"><p class="admonition-title">Riga di stato extra</p><p> Opzioni per la linea supplementare</p></div><p>Per aggiungere informazioni extra devi attivare la riga di stato extra.</p><div class="admonition xdripitem"><p class="admonition-title">Riga di stato extra <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Testo Aggiuntivo</p></div><p>Puoi far calcolare alcune statistiche sulle ultime 24 ore. Per impostazione predefinita partono dalla mezzanotte.</p><div class="admonition xdripitem"><p class="admonition-title">Finestra scorrevole 24 ore <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Per statistica usa le ultime 24 H invece di iniziare a mezzanotte.</p></div><p>C&#39;è un lungo elenco di informazioni extra che puoi mostrare.<br> Seleziona solo quelle che ti serve davvero vedere ogni 5 minuti.</p><div class="admonition xdripitem"><p class="admonition-title">Media <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Valore medio di oggi.</p></div><div class="admonition xdripitem"><p class="admonition-title">A1c DCCT <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Stima HbA1c in formato DCCT (%)</p></div><div class="admonition xdripitem"><p class="admonition-title">A1c IFCC <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Stima HbA1c in formato IFCC (mmol/mol)</p></div><div class="admonition xdripitem"><p class="admonition-title">In Percentuale <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Percentuale di valori nella gamma.</p></div><div class="admonition xdripitem"><p class="admonition-title">Alta Percentuale <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Percentuale di valori sopra la gamma.</p></div><div class="admonition xdripitem"><p class="admonition-title">% BASSO <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Percentuale di valori sotto la gamma.</p></div><div class="admonition xdripitem"><p class="admonition-title">Deviazione Standard <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Mostra deviazione standard dei valori.</p></div><div class="admonition xdripitem"><p class="admonition-title">CHO totali <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Mostra la somma dei CHO</p></div><div class="admonition xdripitem"><p class="admonition-title">Insulina totale <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Mostra la somma dei boli insulinici</p></div><div class="admonition xdripitem"><p class="admonition-title">Stato Esterno <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Mostra lo stato di altre applicazioni come AndroidAPS</p></div><div class="admonition xdripitem"><p class="admonition-title">Stato del micro <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Mostra informazioni sullo stato del micro se disponibile</p></div><div class="admonition xdripitem"><p class="admonition-title">Rapporto CHO/Insulina <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Mostra rapporto CHO/insulina del trattamento</p></div><div class="admonition xdripitem"><p class="admonition-title">Percentuale di pacchetti bluetooth ricevuti <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Percentuale di letture ricevute dal sensore</p></div><div class="admonition xdripitem"><p class="admonition-title">Percentuale di ricezione pacchetti bluetooth in tempo reale <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Percentuale di letture ricevute in tempo reale (non ricuperate dopo). Solo G5 modalità nativa</p></div><div class="admonition xdripitem"><p class="admonition-title">Valutazione di accuratezza <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Mostra l&#39;accuratezza della calibrazione sugli ultimi 3 giorni</p></div><div class="admonition xdripitem"><p class="admonition-title">Tempo <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Ora corrente</p></div><div class="admonition xdripitem"><p class="admonition-title">Dati Calibrazione (lungo) <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Mostra pendenza e origine in forma estesa.</p></div><div class="admonition xdripitem"><p class="admonition-title">Dati Calibrazione (corto) <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Mostra pendenza e origine in forma ridotta.</p></div><div class="admonition xdripitem"><p class="admonition-title">Plugin di calibrazione <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Mostra pendenza e glucosio dal plugin attivo</p></div><p>Puoi aggiungere queste informazioni extra anche al tuo <a href="./mainUI.html#widget">widget</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Mostra su widget <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Mostra la riga di stato supplementare anche sul widget</p></div><h3 id="advanced-calibration" tabindex="-1"><a href="./../calibrate/advancedcal.html">Calibrazione avanzata</a> <a class="header-anchor" href="#advanced-calibration" aria-label="Permalink to &quot;[Calibrazione avanzata](../calibrate/advancedcal) {#advanced-calibration}&quot;">​</a></h3><p>Vedi la sezione dedicata.</p><div class="admonition xdripitem"><p class="admonition-title">Calibrazione avanzata</p><p> Opzioni supplementari relative alle calibrazioni</p></div><h3 id="bluetooth-settings" tabindex="-1"><a href="./bluetooth.html">Impostazioni Bluetooth</a> <a class="header-anchor" href="#bluetooth-settings" aria-label="Permalink to &quot;[Impostazioni Bluetooth](./bluetooth) {#bluetooth-settings}&quot;">​</a></h3><p>Vedi la sezione dedicata.</p><div class="admonition xdripitem"><p class="admonition-title">Impostazioni Bluetooth</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_bluetooth_settings_grey600_48dp.png" style="width:5%;"> Impostazioni Bluetooth avanzate</p></div><h3 id="bluereader-settings" tabindex="-1">Impostazioni blueReader <a class="header-anchor" href="#bluereader-settings" aria-label="Permalink to &quot;Impostazioni blueReader {#bluereader-settings}&quot;">​</a></h3><p>Impostazioni per il bridge Libre <a href="https://www.startnext.com/en/bluereader/wall" target="_blank" rel="noreferrer">pionieristico</a> di Sandra.</p><div class="admonition xdripitem"><p class="admonition-title">Impostazioni blueReader</p><p> Impostazioni avanzate blueReader</p></div><h3 id="advanced-settings-for-libre-2" tabindex="-1">Impostazioni avanzate per Libre 2 <a class="header-anchor" href="#advanced-settings-for-libre-2" aria-label="Permalink to &quot;Impostazioni avanzate per Libre 2 {#advanced-settings-for-libre-2}&quot;">​</a></h3><p>Mostra informazioni aggiuntive per i sensori Libre 2</p><div class="admonition xdripitem"><p class="admonition-title">Impostazioni avanzate per Libre 2</p></div><p>Mostra i valori grezzi sul <a href="./display.html#graph-settings">grafico principale</a></p><div class="admonition xdripitem"><p class="admonition-title">Mostra i valori grezzi nel grafico <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Attiva per mostrare i valori grezzi nel grafico.</p></div><img src="'+s+'" style="zoom:75%;"><p>Mostra più informazioni nello stato</p><div class="admonition xdripitem"><p class="admonition-title">Mostra informazioni sensore nello stato <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Attiva per mostrare ulteriori informazioni nello stato, per il sensore Libre 2.</p></div><h3 id="aggressive-service-restarts" tabindex="-1">Riavvio servizio aggressivo <a class="header-anchor" href="#aggressive-service-restarts" aria-label="Permalink to &quot;Riavvio servizio aggressivo {#aggressive-service-restarts}&quot;">​</a></h3><p>Attivando questa opzione si provoca un <a href="./../troubleshoot/systemstatus.html#restart-collector-forget-device">riavvio del collector</a> quando vengono rilevati dati mancanti. Può essere utile se hai problemi di connessione.</p><div class="admonition xdripitem"><p class="admonition-title">Riavvio servizio aggressivo <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Riavvia ripetutamente il servizio di raccolta in qualsiasi dubbio di dati mancanti. Abilitare solo se si perdono dati.</p></div><h3 id="interpret-raw-values" tabindex="-1">Interpreta Valori Grezzi <a class="header-anchor" href="#interpret-raw-values" aria-label="Permalink to &quot;Interpreta Valori Grezzi {#interpret-raw-values}&quot;">​</a></h3><p>Mostra i dati quando non sono disponibili sul ricevitore Dexcom.</p><div class="admonition xdripitem"><p class="admonition-title">Interpreta Valori Grezzi <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Se usi Condividi, xDrip mostrerà i valori quando sono normalmente nascosti sul ricevitore.</p></div><h3 id="extra-logging-settings" tabindex="-1">Impostazioni di log supplementari <a class="header-anchor" href="#extra-logging-settings" aria-label="Permalink to &quot;Impostazioni di log supplementari {#extra-logging-settings}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Impostazioni di log supplementari</p></div><p>Queste opzioni non sono più usate.</p><div class="admonition xdripitem"><p class="admonition-title">Abilita Logging remoto <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Archivia i log per la ricerca di problemi <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><p>Aggiungere tag extra è utile per il debug, perché inserisce tracce specifiche nel log.</p><div class="admonition xdripitem"><p class="admonition-title">Tag aggiuntivi per la registrazione</p></div><p>Devi sapere cosa vuoi analizzare e impostare il livello corretto. Assicurati di inserire tag validi per evitare che xDrip vada in crash.</p><img src="'+n+'" style="zoom:75%;"><h3 id="show-data-tables" tabindex="-1">Mostra Datatables <a class="header-anchor" href="#show-data-tables" aria-label="Permalink to &quot;Mostra Datatables {#show-data-tables}&quot;">​</a></h3><p>Questa funzione è estremamente utile se calibri con l&#39;algoritmo di xDrip (non nativo).<br> Aggiunge due voci nel menu laterale per visualizzare le tabelle di calibrazione e dei dati.</p><div class="admonition xdripitem"><p class="admonition-title">Mostra Datatables <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Mostra le tabelle di calibrazione e glicemia nel menu ☰.</p></div><p><em>Nota: il grafico di calibrazione non viene mostrato in modalità nativa.</em></p><h3 id="display-bridge-battery" tabindex="-1">Visualizzare Ponte Batteria <a class="header-anchor" href="#display-bridge-battery" aria-label="Permalink to &quot;Visualizzare Ponte Batteria {#display-bridge-battery}&quot;">​</a></h3><p>Puoi mostrare il livello della batteria del bridge Bluetooth nella schermata principale. Vale anche per i bridge Libre Bluetooth.<br> In modalità follower molto probabilmente mostrerà il livello della batteria del telefono master invece di quello del bridge.</p><div class="admonition xdripitem"><p class="admonition-title">Visualizzare Ponte Batteria <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Scegli per visualizzare il livello della batteria del trasmettitore</p></div><img src="'+l+'" style="zoom:75%;"><h3 id="disable-battery-warning" tabindex="-1">Disabilita Allarme Batteria Scarica <a class="header-anchor" href="#disable-battery-warning" aria-label="Permalink to &quot;Disabilita Allarme Batteria Scarica {#disable-battery-warning}&quot;">​</a></h3><p>Disattiva gli avvisi di batteria per i bridge</p><div class="admonition xdripitem"><p class="admonition-title">Disabilita Allarme Batteria Scarica <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Disabilita l&#39;avviso di batteria trasmettitore quasi scarica nella schermata home. (Solo per i ricevitori fai da te.)</p></div><h3 id="database-automatic-maintenance" tabindex="-1">Manutenzione automatica del database <a class="header-anchor" href="#database-automatic-maintenance" aria-label="Permalink to &quot;Manutenzione automatica del database {#database-automatic-maintenance}&quot;">​</a></h3><p>Salva il Database ogni giorno esporta effettivamente il file del database ogni giorno prima di fare pulizia. Occupa molta memoria del dispositivo e non è consigliato.</p><p>Le esportazioni del database vengono salvate nella stessa cartella delle esportazioni manuali: <code>/storage/emulated/0/xDrip</code> o <code>Memoria interna/xDrip</code>.</p><div class="admonition xdripitem"><p class="admonition-title">Salva il Database ogni giorno <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Consente al servizio di pulizia giornaliero di salvare il database prima di svuotarlo</p></div><h4 id="glucose-retention" tabindex="-1">Ritenzione del glucosio <a class="header-anchor" href="#glucose-retention" aria-label="Permalink to &quot;Ritenzione del glucosio {#glucose-retention}&quot;">​</a></h4><p>Ritenzione del glucosio elimina automaticamente i dati più vecchi del numero di giorni selezionato.<br> Zero significa non eliminare nulla. Il valore predefinito è 180 giorni, quindi le nuove installazioni eliminano automaticamente i dati più vecchi di 180 giorni, a meno che tu non lo modifichi. Puoi usare 90 giorni se usi un backup nel cloud come Nightscout, così avrai comunque tutte le statistiche disponibili in xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Ritenzione del glucosio</p><p> Elimina vecchi dati. Tenere solo gli ultimi n giorni. 0 = non cancellare nulla</p></div><h3 id="other-miscellaneous-options" tabindex="-1"><a href="./misc.html">Altre opzioni</a> <a class="header-anchor" href="#other-miscellaneous-options" aria-label="Permalink to &quot;[Altre opzioni](./misc) {#other-miscellaneous-options}&quot;">​</a></h3><p>Vedi la sezione dedicata.</p><div class="admonition xdripitem"><p class="admonition-title">Altre opzioni</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',86)])])}const A=r(c,[["render",u]]);export{I as __pageData,A as default};
